<!-- 실제 API 우선, API 장애 시 명시된 데모 행으로 관리 화면을 끊기지 않게 보여줍니다. -->
<script setup>
import { computed, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useAuthSession } from "@/stores/auth";
import { adminManagementService } from "@/services/adminManagementService";
const route=useRoute(), router=useRouter(), { setAccessToken }=useAuthSession();
const section=computed(()=>route.params.section), rows=ref([]), loading=ref(false), error=ref(""), demoMode=ref(false), search=ref(""), statusFilter=ref("ALL"), viewMode=ref("card");
const titles={orders:"주문·배송 관리",products:"상품 관리",members:"회원 관리",notices:"공지사항 관리",qna:"QnA 관리"};
const detail={orders:"주문 현황과 취소·반품 신청을 확인하고 배송 상태를 처리합니다.",products:"상품별 판매·재고·리뷰 지표를 확인합니다.",members:"활성화·차단·비활성화 회원을 관리합니다.",notices:"공지 등록, 수정, 삭제와 현재 목록을 관리합니다.",qna:"전체·답변 대기 문의를 분류하여 답변합니다."};
const loaders={orders:adminManagementService.getOrders,products:adminManagementService.getProducts,members:adminManagementService.getMembers,notices:adminManagementService.getNotices,qna:adminManagementService.getManagedQnas};
const demoRows={orders:[{orderId:"DEMO-1001",memberName:"데모 회원",totalPrice:48000,status:"PREPARING",requestType:"-"},{orderId:"DEMO-1002",memberName:"데모 회원",totalPrice:32000,status:"SHIPPING",requestType:"RETURN"}],products:[{productId:"DEMO-01",name:"강아지 데일리 사료",stock:18,salesCount:42,soldOut:false},{productId:"DEMO-02",name:"고양이 습식 사료",stock:0,salesCount:8,soldOut:true}],members:[{memberId:"DEMO-01",name:"데모 회원",email:"demo@pawcast.kr",status:"ACTIVE"},{memberId:"DEMO-02",name:"차단 회원",email:"blocked@pawcast.kr",status:"BLOCKED"}],notices:[{noticeId:"DEMO-01",title:"배송 안내",noticeType:"NOTICE",isPinned:true,createdAt:"2026-11-20"}],qna:[{qnaId:"DEMO-01",memberName:"데모 회원",productName:"강아지 데일리 사료",title:"급여 방법 문의",type:"PRODUCT",answerStatus:"PENDING"}]};
function timeout(task){return Promise.race([task,new Promise((_,reject)=>setTimeout(()=>reject(new Error("API 응답 시간 초과")),5000))]);}
async function load(){loading.value=true;error.value="";rows.value=[];demoMode.value=false;try{const result=await timeout(loaders[section.value]());rows.value=Array.isArray(result)?result:[];}catch(cause){error.value=`${cause.message||"데이터를 불러오지 못했습니다."} 임시 운영 화면을 표시합니다.`;rows.value=demoRows[section.value]||[];demoMode.value=true;}finally{loading.value=false;}}
const filteredRows=computed(()=>rows.value.filter((row)=>{const matches=Object.values(row).join(" ").toLowerCase().includes(search.value.toLowerCase());const status=row.status||row.orderStatus||row.answerStatus||"ALL";return matches&&(statusFilter.value==="ALL"||status===statusFilter.value);}));
const columns=computed(()=>filteredRows.value.length?Object.keys(filteredRows.value[0]):[]);
function exportCsv(){const data=[columns.value,...filteredRows.value.map(row=>columns.value.map(key=>row[key]??""))];const url=URL.createObjectURL(new Blob([`\uFEFF${data.map(row=>row.join(",")).join("\n")}`],{type:"text/csv;charset=utf-8"}));const link=document.createElement("a");link.href=url;link.download=`pawcast-${section.value}.csv`;link.click();URL.revokeObjectURL(url);}
async function changeStatus(row,event){if(demoMode.value)return;try{await adminManagementService.changeOrderStatus(row.orderId||row.id,event.target.value);await load();}catch(cause){error.value=cause.message||"상태를 변경하지 못했습니다.";}}
function logout(){setAccessToken("");router.push("/login");} watch(section,load);onMounted(load);
</script>
<template><div class="admin-operations"><aside><b>PAWCAST</b><span>관리자 페이지</span><nav><RouterLink to="/admin/dashboard">대시보드</RouterLink><RouterLink to="/admin/sales">매출 분석</RouterLink><RouterLink to="/admin/orders">주문·배송 관리</RouterLink><RouterLink to="/admin/products">상품 관리</RouterLink><RouterLink to="/admin/members">회원 관리</RouterLink><RouterLink to="/admin/notices">공지사항 관리</RouterLink><RouterLink to="/admin/qna">QnA 관리</RouterLink></nav><button @click="logout">로그아웃</button></aside><main><header><small>ADMIN MANAGEMENT</small><h1>{{titles[section]}}</h1><p>{{detail[section]}}</p></header><section class="toolbar"><input v-model="search" placeholder="주문번호·상품명·회원명 검색"><select v-model="statusFilter"><option value="ALL">전체 상태</option><option value="PREPARING">상품 준비</option><option value="SHIPPING">배송 중</option><option value="DELIVERED">배송 완료</option><option value="PENDING">답변 대기</option></select><button v-if="section==='members'" :class="{selected:viewMode==='card'}" @click="viewMode='card'">카드형</button><button v-if="section==='members'" :class="{selected:viewMode==='list'}" @click="viewMode='list'">리스트형</button><button class="export" @click="exportCsv">엑셀용 CSV 다운로드</button></section><p v-if="loading">불러오는 중입니다.</p><div v-else><p v-if="error" class="error">{{error}}</p><p v-if="demoMode" class="demo">DEMO DATA · API 정상화 시 실제 데이터로 자동 전환됩니다.</p><div v-if="filteredRows.length" :class="['table-wrap',{cards:section==='members'&&viewMode==='card'}]"><table v-if="!(section==='members'&&viewMode==='card')"><thead><tr><th v-for="key in columns" :key="key">{{key}}</th><th v-if="section==='orders'">배송 상태 처리</th><th v-if="section==='qna'">답변 처리</th></tr></thead><tbody><tr v-for="(row,index) in filteredRows" :key="row.id||row.orderId||index"><td v-for="key in columns" :key="key">{{typeof row[key]==='object'?'-':row[key]}}</td><td v-if="section==='orders'"><select :disabled="demoMode" :value="row.status||row.orderStatus" @change="changeStatus(row,$event)"><option value="PAID">결제 완료</option><option value="PREPARING">상품 준비</option><option value="SHIPPING">배송 중</option><option value="DELIVERED">배송 완료</option></select></td><td v-if="section==='qna'"><button :disabled="demoMode">답변하기</button></td></tr></tbody></table><article v-else v-for="(row,index) in filteredRows" :key="row.memberId||index"><b>{{row.name||row.memberName}}</b><span>{{row.email}}</span><em>{{row.status}}</em><button :disabled="demoMode">상태 변경</button></article></div><p v-else>검색 조건에 맞는 데이터가 없습니다.</p></div></main></div></template>
<style scoped>
.admin-operations{display:grid;grid-template-columns:240px 1fr;min-height:100vh;background:#f7f5f2;color:#3d281b}.admin-operations aside{display:flex;flex-direction:column;gap:8px;background:#fffcf7;border-right:1px solid #eadfd3;padding:30px 18px}.admin-operations aside>b{font-size:26px;color:#875738}.admin-operations aside>span{color:#987e6b;font-size:12px}.admin-operations nav{display:grid;gap:6px;margin-top:22px}.admin-operations a,.admin-operations button{border:0;border-radius:10px;background:transparent;padding:12px;color:#4b3425;font:inherit;font-weight:800;text-align:left;text-decoration:none}.admin-operations a:hover,.admin-operations a.router-link-active{background:#a66b3f;color:#fff}.admin-operations aside>button{margin-top:auto;border:1px solid #d8bca2;background:#fff}.admin-operations main{padding:48px clamp(24px,6vw,88px);overflow:auto}.admin-operations header small{color:#a66838;font-weight:900;letter-spacing:.12em}.admin-operations h1{margin:8px 0}.admin-operations header p{color:#917866}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:26px 0 12px}.toolbar input,.toolbar select{min-height:38px;border:1px solid #ddc9b8;border-radius:8px;background:#fff;padding:0 10px}.toolbar button{border:1px solid #d9b898;background:#fff;padding:8px 12px}.toolbar .selected,.toolbar .export{background:#a66b3f;color:#fff}.error,.demo{padding:10px 0}.error{color:#b34d3b}.demo{color:#9b632d;font-weight:800}.table-wrap{overflow:auto;border:1px solid #e8d8ca;border-radius:14px;background:#fff}.table-wrap table{width:100%;border-collapse:collapse}.table-wrap th,.table-wrap td{padding:13px;border-bottom:1px solid #f0e7df;text-align:left;white-space:nowrap}.table-wrap th{background:#fffaf5}.table-wrap select,.table-wrap td button{border:1px solid #ddc9b8;border-radius:7px;background:#fff;padding:7px}.cards{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;border:0;background:transparent}.cards article{display:grid;gap:8px;border:1px solid #e8d8ca;border-radius:12px;background:#fff;padding:18px}.cards article span{color:#806653}.cards article em{font-style:normal;color:#a66838;font-weight:800}.cards article button{border:1px solid #d8bca2;border-radius:8px;background:#fff;padding:7px}@media(max-width:850px){.admin-operations{grid-template-columns:1fr}.admin-operations nav{grid-template-columns:repeat(2,1fr)}.cards{grid-template-columns:1fr}}
</style>
